import subprocess,sys,json,os
def load(p):
    w,h=[int(x) for x in subprocess.check_output(['ffprobe','-v','error','-select_streams','v','-show_entries','stream=width,height','-of','csv=p=0',p]).decode().strip().split(',')]
    raw=subprocess.check_output(['ffmpeg','-v','error','-i',p,'-f','rawvideo','-pix_fmt','rgba','-'])
    return w,h,raw
rsi=sys.argv[1]; m=json.load(open(os.path.join(rsi,'meta.json'))); S=m['size']['x']
for st in m['states']:
    p=os.path.join(rsi,st['name']+'.png'); w,h,raw=load(p)
    cols=w//S; nd=st.get('directions',1); nf=len(st.get('delays',[[1]])[0])
    out=[]
    for d in range(nd):
        row=[]
        for f in range(nf):
            i=d*nf+f; cx=(i%cols)*S; cy=(i//cols)*S
            xs=[];ys=[]
            for y in range(S):
                for x in range(S):
                    if raw[((cy+y)*w+cx+x)*4+3]>0: xs.append(x);ys.append(y)
            row.append((min(xs),min(ys),max(xs),max(ys)) if xs else None)
        out.append(row)
    print(st['name'])
    for d,row in enumerate(out): print('  d%d'%d,row)
